"""Default XDG configuration.

``praxis-prime config`` writes these files. Compliance dials are included and
set to off. Writing the files does not start the daemon and does not enable a
dial.

TODO: ARCHITECTURE §17 and §25.
"""

from __future__ import annotations

import os
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path

from praxis_prime.paths import config_dir
from praxis_prime.policy.dials import default_positions

_CONFIG_HEADER = """\
# Praxis Prime configuration (alpha).
# Generated by `praxis-prime config`. Safe to edit. Contains no secrets.
#
# Secrets do not belong in this file. API keys live in secrets.env
# (mode 0600) or the environment. No model provider is selected until
# `praxis-prime setup` or the web wizard writes one. Example specs look
# like ollama:qwen3:8b. Those examples are not defaults.
#
# Compliance dials default to off (ARCHITECTURE §17). A dial position is one
# of: off, monitor, enforce. Dial hooks do nothing while a dial is off.
# The baseline safety spine is not a dial and cannot be turned off.
#
# The Decision Engine is local. It does not call a hosted decision service.
# decide.prescreen defaults to false, so approvals are unchanged until you
# turn it on. The engine cannot auto-approve git push, force operations,
# deletes of tracked files, or writes outside the task worktree.
#
# mcp.serve stays false. Nothing listens for other agents until you run
# `praxis-prime mcp serve`. Browser profile defaults to a disposable
# directory. Playwright is optional; without it the browser tool uses web_fetch.
#
# tools.read_roots and tools.read_allow are empty. The session workspace is
# the only directory reads may touch until you add an absolute path here.
# tools.fetch_allow is empty, so web_fetch refuses loopback, private,
# link-local, and cloud-metadata addresses. A relative path in those lists
# is ignored.
#
# gateway.bearer defaults to true. Once an account exists, the loopback
# bearer token is an owner-equivalent credential. Set bearer = false to
# refuse it. Cookie sessions still work. With no accounts, the token stays
# required so the gateway is not left open.
"""

_PROFILE_HEADER = """\
# Which compliance dials are active. An empty list means every dial is off.
# TODO: ARCHITECTURE §17.1. This file does not enable enforcement.
"""


@dataclass(frozen=True, slots=True)
class ConfigWriteResult:
    """Result of attempting to write the default config."""

    config_path: Path
    profile_path: Path
    wrote: bool


