def default_profile_document() -> dict[str, object]:
    return {"profile": {"name": "default", "mode": "ask", "dials": []}}


def render_config_toml() -> str:
    return _CONFIG_HEADER + "\n" + dumps_toml(default_config_document())


def render_profile_toml() -> str:
    return _PROFILE_HEADER + "\n" + dumps_toml(default_profile_document())


def write_default_config(directory: Path, *, force: bool = False) -> ConfigWriteResult:
    """Write ``config.toml`` and ``policy/profile.toml`` under ``directory``.

    Existing files are left alone unless ``force`` is true. ``directory`` is
    the Praxis Prime config directory itself, not ``~/.config``.
    """
    root = Path(directory)
    config_path = root / "config.toml"
    profile_path = root / "policy" / "profile.toml"
    if config_path.exists() and not force:
        return ConfigWriteResult(config_path, profile_path, wrote=False)
    _atomic_write(config_path, render_config_toml())
    _atomic_write(profile_path, render_profile_toml())
    return ConfigWriteResult(config_path, profile_path, wrote=True)


def resolve_config_dir(
    explicit: str | None = None,
    env: Mapping[str, str] | None = None,
) -> Path:
    if explicit:
        return Path(explicit)
    return config_dir(env)


def dumps_toml(data: Mapping[str, object]) -> str:
    """Serialize a small nested mapping to TOML. Enough for the default file."""
    chunks: list[str] = []
    for key, value in data.items():
        if not isinstance(value, dict):
            raise TypeError(f"top-level {key} must be a table")
        _emit_table(chunks, key, value)
    return "".join(chunks)


def _emit_table(chunks: list[str], prefix: str, table: Mapping[str, object]) -> None:
    scalars: list[tuple[str, object]] = []
    nested: list[tuple[str, Mapping[str, object]]] = []
    for key, value in table.items():
        if isinstance(value, dict):
            nested.append((key, value))
        else:
            scalars.append((key, value))
    if scalars or not nested:
        chunks.append(f"[{prefix}]\n")
        for key, value in scalars:
            chunks.append(f"{key} = {format_toml(value)}\n")
        chunks.append("\n")
    for key, value in nested:
        _emit_table(chunks, f"{prefix}.{key}", value)


def format_toml(value: object) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return repr(value)
    if isinstance(value, str):
        escaped = value.replace("\\", "\\\\").replace('"', '\\"')
        return f'"{escaped}"'
    if isinstance(value, list):
        inner = ", ".join(format_toml(item) for item in value)
        return f"[{inner}]"
    raise TypeError(f"unsupported TOML value: {type(value).__name__}")


def describe_write(result: ConfigWriteResult) -> str:
    """Human-readable summary for the CLI."""
    if not result.wrote:
        return (
            f"praxis-prime config: already exists at {result.config_path}\n"
            "Leave it in place, or pass --force to overwrite.\n"
        )
    count = len(default_positions())
    return (
        f"praxis-prime config: wrote {result.config_path}\n"
        f"praxis-prime config: wrote {result.profile_path}\n"
        f"Compliance dials: {count} configured, all off.\n"
    )


def _atomic_write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.tmp-{os.getpid()}")
    temporary.write_text(text, encoding="utf-8")
    temporary.replace(path)
